// Load runtime secrets from AWS Secrets Manager into process.env.
//
// On AWS nothing secret lives in the code, the AMI, the launch template or a
// .env file on disk. The instance's IAM role may read exactly two secrets:
//
//  - APP_SECRET_ID: a JSON object of settings, e.g.
//      { "JWT_SECRET": "...", "EMAIL_USER": "...", "EMAIL_PASS": "..." }
//    every key is copied into the environment;
//  - DB_SECRET_ID:  { "username": "...", "password": "..." } for MongoDB,
//    generated by CloudFormation. Together with MONGO_HOST it becomes
//    MONGO_URI, so the database password is never written down anywhere.
//
// Without these variables (local development) nothing happens and the usual
// .env file is used. Values already in the environment win, so a one-off
// override on the command line still works.

const readJsonSecret = async (client, GetSecretValueCommand, secretId) => {
  const { SecretString } = await client.send(new GetSecretValueCommand({ SecretId: secretId }));
  try {
    return JSON.parse(SecretString || "{}");
  } catch {
    throw new Error(`Secret ${secretId} is not a JSON object`);
  }
};

// mongodb://user:pass@host:27017/db?replicaSet=rs0&authSource=admin
export const buildMongoUri = ({ username, password, host, database = "scipark", replicaSet = "rs0" }) => {
  const auth = `${encodeURIComponent(username)}:${encodeURIComponent(password)}`;
  const hostPort = host.includes(":") ? host : `${host}:27017`;
  return `mongodb://${auth}@${hostPort}/${database}?replicaSet=${replicaSet}&authSource=admin`;
};

export const loadSecrets = async () => {
  const appSecretId = process.env.APP_SECRET_ID;
  const dbSecretId = process.env.DB_SECRET_ID;
  if (!appSecretId && !dbSecretId) return { loaded: 0, source: "env" };

  // Imported lazily so local development never needs the SDK configured.
  const { SecretsManagerClient, GetSecretValueCommand } = await import("@aws-sdk/client-secrets-manager");
  const client = new SecretsManagerClient({});
  let loaded = 0;

  if (appSecretId) {
    const values = await readJsonSecret(client, GetSecretValueCommand, appSecretId);
    for (const [key, value] of Object.entries(values)) {
      if (process.env[key] === undefined && value !== null && value !== "") {
        process.env[key] = String(value);
        loaded += 1;
      }
    }
  }

  if (dbSecretId && !process.env.MONGO_URI) {
    if (!process.env.MONGO_HOST) throw new Error("DB_SECRET_ID is set but MONGO_HOST is not");
    const { username, password } = await readJsonSecret(client, GetSecretValueCommand, dbSecretId);
    if (!username || !password) throw new Error(`Secret ${dbSecretId} needs "username" and "password"`);
    process.env.MONGO_URI = buildMongoUri({
      username,
      password,
      host: process.env.MONGO_HOST,
      database: process.env.MONGO_DB || "scipark",
      replicaSet: process.env.MONGO_REPLICA_SET || "rs0",
    });
    loaded += 1;
  }

  return { loaded, source: "secretsmanager" };
};

export default { loadSecrets, buildMongoUri };
